# owner: platform
"""Find the stretches of opening hours that nobody is covering."""

from typing import Iterable, List

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_clock


def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, like gap 12:00-13:00 (60 min).

    ValueError when any worked span falls outside opening hours.
    """
    spans = list(worked)
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(
                "worked span {}-{} is outside opening hours {}-{}".format(
                    format_clock(span.start),
                    format_clock(span.end),
                    format_clock(opening.start),
                    format_clock(opening.end),
                )
            )

    result = []
    cursor = opening.start
    for span in merge_spans(spans):
        if span.start > cursor:
            result.append(_label(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        result.append(_label(cursor, opening.end))
    return result


def _label(start: int, end: int) -> str:
    return "gap {}-{} ({} min)".format(
        format_clock(start), format_clock(end), end - start
    )
