cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span
from hourglass.parsing import parse_span


def spans(*texts):
    result = []
    for text in texts:
        result.append(parse_span(text))
    return result


OPEN = parse_span("09:00-17:00")


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = spans("10:00-16:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 16:00-17:00 (60 min)"],
        )

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_coverage_has_no_gaps(self):
        worked = spans("09:00-13:00", "13:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_overlapping_and_unordered_spans(self):
        worked = spans("14:00-17:00", "09:00-13:00", "11:00-14:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), OPEN)

    def test_accepts_any_iterable(self):
        gen = iter([Span(540, 600)])
        self.assertEqual(find_gaps(gen, Span(540, 660)), ["gap 10:00-11:00 (60 min)"])


if __name__ == "__main__":
    unittest.main()
